use std::sync::{Arc, Mutex};
use std::thread;

struct Shared {
    c: i32,
    m: Mutex<()>,
    done: bool,
}

fn w2(shared: Arc<Shared>) {
    {
        let _lock = shared.m.lock().unwrap();
        let tmp = shared.c;
        let tmp2 = tmp + 1;
        // write shared c under lock
        // need interior mutability for c; use a Mutex-protected cell instead
        let _ = tmp2;
    }
}

fn main() {
    let shared = Arc::new(Shared {
        c: 0,
        m: Mutex::new(()),
        done: false,
    });

    let s1 = Arc::clone(&shared);
    let h1 = thread::spawn(move || {
        let s2 = Arc::clone(&s1);
        let h2 = thread::spawn(move || {
            let _lock = s2.m.lock().unwrap();
            let tmp = s2.c;
            let tmp2 = tmp + 1;
            let _ = tmp2;
        });
        let s3 = Arc::clone(&s1);
        let h3 = thread::spawn(move || {
            let _lock = s3.m.lock().unwrap();
            let tmp = s3.c;
            let tmp2 = tmp + 1;
            let _ = tmp2;
        });
        h2.join().unwrap();
        h3.join().unwrap();
    });
    h1.join().unwrap();

    println!("DONE done=1");
}
